import ast
import os
import subprocess
import sys
import tempfile
import time
import tomllib
import unittest
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional, Tuple

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Import artifacts module if available, otherwise define fallbacks
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        filter_bundle,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback definitions if artifacts.py is not yet available or import fails
    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.replace('\\', '/').split('/')
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Tuple[str, ...] = ('.py',)) -> int:
        return sum(1 for k in filter_bundle(bundle) if k.endswith(suffixes))


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = sum(1 for g in evaluated if g.passed)
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✓" if g.passed else ("✗" if g.status == FAILED else "-")
            lines.append(f"[{status_icon}] {g.name}: {g.status.upper()} ({g.method})")
            if g.detail:
                lines.append(f"    Detail: {g.detail}")
        lines.append("-" * 40)
        lines.append(f"Pass Rate (Evaluated): {self.pass_rate:.2%}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    blocks = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i]
        # Look for start of fenced block
        if line.strip().startswith("```"):
            # Extract language hint if present, though we mostly care about content
            # Try to find a filename in the fence info or preceding comment
            fence_info = line.strip()[3:].strip()

            # Heuristic: Look for a filename in the fence info or the line before
            filename = None
            if fence_info:
                # Sometimes fence info is just the language, sometimes path
                # If it looks like a path, use it
                if '/' in fence_info or '.' in fence_info:
                    filename = fence_info
                else:
                    # Check previous line for a comment like # path/to/file.py
                    if i > 0:
                        prev_line = lines[i-1].strip()
                        if prev_line.startswith('#') and ('/' in prev_line or '.' in prev_line):
                            filename = prev_line.lstrip('#').strip()

            # Collect content until closing fence
            content_lines = []
            i += 1
            while i < len(lines):
                if lines[i].strip().startswith("```"):
                    break
                content_lines.append(lines[i])
                i += 1

            if filename:
                # Clean up filename
                filename = filename.strip()
                if filename.startswith("./"):
                    filename = filename[2:]
                blocks[filename] = "\n".join(content_lines)
            else:
                # If no filename found, we might skip or assign a generic name
                # But spec says "path->content map", so we need a path.
                # If we can't determine path, we can't really use it for gates that check paths.
                # However, for smoke/telemetry, we just need the code.
                # Let's assign a dummy name if none found, but it might fail build/syntax if path is weird.
                # Better to skip if no path is identifiable, as we can't place it correctly.
                pass
        i += 1
    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        # Try to get bundle from workspace object
        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
                source = 'workspace'
            elif isinstance(workspace, dict):
                bundle = workspace
                source = 'workspace'
            elif hasattr(workspace, 'files'):
                bundle = workspace.files
                source = 'workspace'

        # Fallback to deliverable text if bundle is empty
        if not bundle and deliverable_text:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, ('.py',))

        # Create temp dir
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            # Run gates
            gates = []
            gates.append(self._gate_syntax(tmpdir, authored_bundle))
            gates.append(self._gate_build(tmpdir, authored_bundle))
            gates.append(self._gate_smoke(tmpdir, authored_bundle))
            gates.append(self._gate_tests(tmpdir, authored_bundle))
            gates.append(self._gate_telemetry(tmpdir, authored_bundle))

            # Calculate penalty
            failed_count = sum(1 for g in gates if g.status == FAILED)
            score_penalty = failed_count * self.penalty_per_gate

            return VerificationReport(
                gates=gates,
                score_penalty=score_penalty,
                authored_files=authored_files,
                python_files=python_files,
                source=source
            )

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        # Read files from directory
        bundle = {}
        for root, dirs, files in os.walk(workdir):
            # Prune excluded dirs
            dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]

            for file in files:
                full_path = os.path.join(root, file)
                rel_path = os.path.relpath(full_path, workdir)
                if is_generated_path(rel_path) or is_malformed_path(rel_path):
                    continue
                try:
                    with open(full_path, 'r', encoding='utf-8') as f:
                        bundle[rel_path] = f.read()
                except Exception:
                    pass

        # If authored dict provided, use it to filter/override? 
        # Spec says "authored: Optional[Dict[str, str]]". Usually this means the set of files considered authored.
        if authored is not None:
            # Filter bundle to only include keys in authored
            bundle = {k: v for k, v in bundle.items() if k in authored}

        return self.verify_bundle(bundle, source=source)

    def _gate_syntax(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()
        method = "ast.parse"
        py_files = [k for k in bundle if k.endswith('.py')]

        if not py_files:
            return GateResult(
                name="syntax",
                status=FAILED,
                method=method,
                detail="No Python files found.",
                duration_s=time.time() - start
            )

        errors = []
        for path in py_files:
            content = bundle[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        duration = time.time() - start
        if errors:
            return GateResult(
                name="syntax",
                status=FAILED,
                method=method,
                detail="; ".join(errors),
                duration_s=duration
            )

        return GateResult(
            name="syntax",
            status=PASSED,
            method=method,
            detail=f"Successfully parsed {len(py_files)} Python files.",
            duration_s=duration
        )

    def _gate_build(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()
        method = "pip install -e ."

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in bundle
        has_setup_py = 'setup.py' in bundle
        has_setup_cfg = 'setup.cfg' in bundle

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name="build",
                status=FAILED,
                method=method,
                detail="No packaging metadata found (pyproject.toml, setup.py, or setup.cfg).",
                duration_s=time.time() - start
            )

        # Validate pyproject.toml if present
        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                # Must contain at least one of [project], [build-system], or [tool]
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name="build",
                        status=FAILED,
                        method=method,
                        detail="pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool]).",
                        duration_s=time.time() - start
                    )
            except Exception as e:
                return GateResult(
                    name="build",
                    status=FAILED,
                    method=method,
                    detail=f"Failed to parse pyproject.toml: {e}",
                    duration_s=time.time() - start
                )

        # Try pip install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, "-m", "pip", "--version"], 
                           capture_output=True, timeout=10, check=True)

            # Run install
            result = subprocess.run(
                [self.python_executable, "-m", "pip", "install", "-e", ".", "--no-deps", "--no-build-isolation"],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )

            duration = time.time() - start
            if result.returncode == 0:
                return GateResult(
                    name="build",
                    status=PASSED,
                    method=method,
                    detail="Package installed successfully.",
                    duration_s=duration
                )
            else:
                return GateResult(
                    name="build",
                    status=FAILED,
                    method=method,
                    detail=f"pip install failed: {result.stderr}",
                    duration_s=duration
                )
        except FileNotFoundError:
            return GateResult(
                name="build",
                status=SKIPPED,
                method=method,
                detail="pip not available.",
                duration_s=time.time() - start
            )
        except subprocess.TimeoutExpired:
            return GateResult(
                name="build",
                status=FAILED,
                method=method,
                detail="pip install timed out.",
                duration_s=time.time() - start
            )
        except Exception as e:
            return GateResult(
                name="build",
                status=FAILED,
                method=method,
                detail=f"Error during build check: {e}",
                duration_s=time.time() - start
            )

    def _gate_smoke(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()
        method = "subprocess import"

        # Find non-test modules
        # Exclude test files
        test_files = [k for k in bundle if 'test' in os.path.basename(k).lower()]
        non_test_modules = []

        for path in bundle:
            if not path.endswith('.py'):
                continue
            if path in test_files:
                continue

            # Determine module name
            # If it's in src/, strip src/
            rel_path = path
            if rel_path.startswith('src/'):
                rel_path = rel_path[4:]

            # Convert path to module name
            module_name = rel_path.replace('/', '.').replace('\\', '.')
            if module_name.endswith('.py'):
                module_name = module_name[:-3]

            # Skip __init__.py as importing it is trivial/implicit
            if module_name.endswith('.__init__'):
                continue

            non_test_modules.append((path, module_name))

        if not non_test_modules:
            return GateResult(
                name="smoke",
                status=FAILED,
                method=method,
                detail="No importable non-test modules found.",
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        failures = []
        skipped_modules = []

        for path, module_name in non_test_modules:
            try:
                # Run import in subprocess
                code = f"import {module_name}"
                result = subprocess.run(
                    [self.python_executable, "-c", code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                if result.returncode != 0:
                    stderr = result.stderr
                    # Check for ModuleNotFoundError for third-party packages
                    if "ModuleNotFoundError" in stderr:
                        # Heuristic: if it's not our own module, it's likely third-party
                        # We can't easily distinguish, but spec says "uninstalled third-party packages"
                        # If the error is about a package that isn't in our bundle, it's third-party.
                        # Simple check: if the missing module name isn't in our bundle's top-level packages
                        # For now, assume if it's not a syntax error, it might be third-party.
                        # But spec says: "If module imports fail solely with ModuleNotFoundError for uninstalled third-party packages... return SKIPPED"
                        # If ANY module fails with ModuleNotFoundError, we might skip the whole gate?
                        # "If no importable modules exist or any module fails with a syntax or runtime error, return FAILED."
                        # "If module imports fail solely with ModuleNotFoundError... return SKIPPED"

                        # Let's collect these. If we have other failures, it's FAILED.
                        # If we only have ModuleNotFoundError, it's SKIPPED.
                        skipped_modules.append((module_name, stderr))
                    else:
                        failures.append((module_name, stderr))
            except Exception as e:
                failures.append((module_name, str(e)))

        duration = time.time() - start

        if failures:
            return GateResult(
                name="smoke",
                status=FAILED,
                method=method,
                detail=f"Import failures: {failures}",
                duration_s=duration
            )

        if skipped_modules:
            return GateResult(
                name="smoke",
                status=SKIPPED,
                method=method,
                detail=f"Skipped due to missing third-party dependencies: {skipped_modules}",
                duration_s=duration
            )

        return GateResult(
            name="smoke",
            status=PASSED,
            method=method,
            detail=f"Successfully imported {len(non_test_modules)} modules.",
            duration_s=duration
        )

    def _gate_tests(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()
        method = "pytest"

        # Find test files
        test_files = [k for k in bundle if 'test' in os.path.basename(k).lower() and k.endswith('.py')]

        if not test_files:
            return GateResult(
                name="tests",
                status=FAILED,
                method=method,
                detail="No test files found.",
                duration_s=time.time() - start
            )

        # Prepare PYTHONPATH
        env = os.environ.copy()
        src_dir = os.path.join(workdir, 'src')
        python_path = f"{workdir}:{src_dir}"
        if 'PYTHONPATH' in env:
            env['PYTHONPATH'] = f"{python_path}:{env['PYTHONPATH']}"
        else:
            env['PYTHONPATH'] = python_path

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, "-m", "pytest", "--version"], 
                           capture_output=True, timeout=10, check=True)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            method = "pytest"
            try:
                # Run pytest on test files
                # We need to pass the paths relative to workdir
                test_paths = [os.path.join(workdir, f) for f in test_files]
                result = subprocess.run(
                    [self.python_executable, "-m", "pytest", "-v"] + test_paths,
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                duration = time.time() - start
                if result.returncode == 0:
                    return GateResult(
                        name="tests",
                        status=PASSED,
                        method=method,
                        detail="All tests passed.",
                        duration_s=duration
                    )
                else:
                    # Check if failure is due to ModuleNotFoundError
                    if "ModuleNotFoundError" in result.stderr or "ModuleNotFoundError" in result.stdout:
                        # Check if it's a third-party package
                        # If tests failed because of missing deps, skip
                        # But if tests failed because of assertion, fail
                        # Pytest exit code 1 is tests failed, 2 is interrupted, 3 internal error, 4 usage error, 5 no tests collected
                        # If it's 1, we need to check if it's import error or test failure
                        # Simple heuristic: if "ModuleNotFoundError" is in output, it's likely import issue
                        return GateResult(
                            name="tests",
                            status=SKIPPED,
                            method=method,
                            detail=f"Tests skipped due to missing dependencies: {result.stderr[:500]}",
                            duration_s=duration
                        )
                    return GateResult(
                        name="tests",
                        status=FAILED,
                        method=method,
                        detail=f"Tests failed: {result.stderr[:500]}",
                        duration_s=duration
                    )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name="tests",
                    status=FAILED,
                    method=method,
                    detail="Tests timed out.",
                    duration_s=time.time() - start
                )
            except Exception as e:
                return GateResult(
                    name="tests",
                    status=FAILED,
                    method=method,
                    detail=f"Error running pytest: {e}",
                    duration_s=time.time() - start
                )
        else:
            method = "stdlib unittest"
            # Fallback to stdlib unittest
            # We need to run a script that imports test files and runs tests
            # This is complex to do in a single subprocess call for multiple files
            # We'll write a temporary runner script

            runner_script = os.path.join(workdir, "_test_runner.py")
            with open(runner_script, 'w') as f:
                f.write("import unittest\n")
                f.write("import sys\n")
                f.write("import os\n")
                f.write("import importlib\n")
                f.write("import traceback\n")
                f.write("\n")
                f.write("def run_tests():\n")
                f.write("    loader = unittest.TestLoader()\n")
                f.write("    suite = unittest.TestSuite()\n")
                f.write("    test_files = ")
                f.write(repr(test_files))
                f.write("\n")
                f.write("    for tf in test_files:\n")
                f.write("        try:\n")
                f.write("            # Convert path to module name\n")
                f.write("            mod_name = tf.replace('/', '.').replace('\\\\', '.')\n")
                f.write("            if mod_name.endswith('.py'):\n")
                f.write("                mod_name = mod_name[:-3]\n")
                f.write("            # Try to import\n")
                f.write("            mod = importlib.import_module(mod_name)\n")
                f.write("            # Find TestCase subclasses\n")
                f.write("            for name in dir(mod):\n")
                f.write("                obj = getattr(mod, name)\n")
                f.write("                if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj is not unittest.TestCase:\n")
                f.write("                    suite.addTests(loader.loadTestsFromTestCase(obj))\n")
                f.write("            # Find bare test functions\n")
                f.write("            for name in dir(mod):\n")
                f.write("                if name.startswith('test_'):\n")
                f.write("                    obj = getattr(mod, name)\n")
                f.write("                    if callable(obj):\n")
                f.write("                        # Wrap in a TestCase\n")
                f.write("                        class TestWrapper(unittest.TestCase):\n")
                f.write("                            def test_wrapper(self):\n")
                f.write("                                obj()\n")
                f.write("                        suite.addTest(TestWrapper('test_wrapper'))\n")
                f.write("        except ModuleNotFoundError as e:\n")
                f.write("            print(f'SKIP: {tf} - {e}')\n")
                f.write("        except Exception as e:\n")
                f.write("            print(f'ERROR: {tf} - {e}')\n")
                f.write("            traceback.print_exc()\n")
                f.write("    \n")
                f.write("    runner = unittest.TextTestRunner(verbosity=2)\n")
                f.write("    result = runner.run(suite)\n")
                f.write("    sys.exit(0 if result.wasSuccessful() else 1)\n")
                f.write("\n")
                f.write("if __name__ == '__main__':\n")
                f.write("    run_tests()\n")

            try:
                result = subprocess.run(
                    [self.python_executable, runner_script],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )

                duration = time.time() - start
                if result.returncode == 0:
                    return GateResult(
                        name="tests",
                        status=PASSED,
                        method=method,
                        detail="All tests passed.",
                        duration_s=duration
                    )
                else:
                    if "ModuleNotFoundError" in result.stderr or "ModuleNotFoundError" in result.stdout:
                        return GateResult(
                            name="tests",
                            status=SKIPPED,
                            method=method,
                            detail=f"Tests skipped due to missing dependencies: {result.stderr[:500]}",
                            duration_s=duration
                        )
                    return GateResult(
                        name="tests",
                        status=FAILED,
                        method=method,
                        detail=f"Tests failed: {result.stderr[:500]}",
                        duration_s=duration
                    )
            except Exception as e:
                return GateResult(
                    name="tests",
                    status=FAILED,
                    method=method,
                    detail=f"Error running tests: {e}",
                    duration_s=time.time() - start
                )

    def _gate_telemetry(self, workdir: str, bundle: Dict[str, str]) -> GateResult:
        start = time.time()
        method = "ast analysis"

        py_files = [k for k in bundle if k.endswith('.py')]

        if not py_files:
            return GateResult(
                name="telemetry",
                status=FAILED,
                method=method,
                detail="No Python files found.",
                duration_s=time.time() - start
            )

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span',
            'start_span',
            'get_tracer',
            'get_tracer_provider',
            'set_tracer_provider',
            'get_meter'
        }

        for path in py_files:
            content = bundle[path]
            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls to tracer methods
                if isinstance(node, ast.Call):
                    func = node.func
                    if isinstance(func, ast.Name):
                        if func.id in tracer_methods:
                            has_call = True
                    elif isinstance(func, ast.Attribute):
                        if func.attr in tracer_methods:
                            has_call = True

        duration = time.time() - start

        if has_import and has_call:
            return GateResult(
                name="telemetry",
                status=PASSED,
                method=method,
                detail="Found OpenTelemetry import and tracer/span calls.",
                duration_s=duration
            )

        if not has_import:
            return GateResult(
                name="telemetry",
                status=FAILED,
                method=method,
                detail="No OpenTelemetry import found.",
                duration_s=duration
            )

        if not has_call:
            return GateResult(
                name="telemetry",
                status=FAILED,
                method=method,
                detail="OpenTelemetry imported but no tracer/span calls found.",
                duration_s=duration
            )

        return GateResult(
            name="telemetry",
            status=FAILED,
            method=method,
            detail="Telemetry requirements not met.",
            duration_s=duration
        )

